flow.chain:
fileScanDir = '../../adm';
fileScanPattern = {{0}};
fileScannerTo = '{"dir":"'+fileScanDir+'","pattern":"'+fileScanPattern+'"}';

codeParser = {{1}};

codeGeneratorBtl = {{2}};
codeGeneratorTo = '{"btl":"'+codeGeneratorBtl+'"}';

fileWriterPackageName = {{3}};
fileWriterTarget = 'target/web';
fileWriterTo = '{"packageName":"'+fileWriterPackageName+'","target":"'+fileWriterTarget+'"}';

THEN(
    beetl,
    ITERATOR(fileScanner.data(fileScannerTo)).DO(CATCH(THEN(
        fileParser,
        codeParser,
        codeGenerator.data(codeGeneratorTo),
        fileWriter.data(fileWriterTo)
    )))
);
